# 1-Click Local Portfolio Sync Script (Code + Resume PDF + Cover Letter PDF + High-DPI Previews + CI Workflow)
$ErrorActionPreference = "Stop"
$b64 = ""
[IO.File]::WriteAllText((Join-Path $PWD ".bundle.b64"), $b64)
node -e "const fs=require('fs'),path=require('path'),zlib=require('zlib');const raw=fs.readFileSync('.bundle.b64','utf8').trim();const b=JSON.parse(zlib.gunzipSync(Buffer.from(raw,'base64')).toString('utf8'));for(const[k,v]of Object.entries(b.text)){fs.mkdirSync(path.dirname(k),{recursive:true});fs.writeFileSync(k,v,'utf8');console.log('Updated text:',k);}for(const[k,v]of Object.entries(b.bin)){fs.mkdirSync(path.dirname(k),{recursive:true});fs.writeFileSync(k,Buffer.from(v,'base64'));console.log('Updated binary:',k,'('+Buffer.from(v,'base64').length+' bytes)');}fs.unlinkSync('.bundle.b64');"
Write-Host "All portfolio files, PDFs, high-DPI previews, and CI workflow synced successfully!" -ForegroundColor Green
